import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in), m = (int) readLong(in);
        long[] fish = new long[n], baits = new long[m];
        for (int k = 0; k < n; k++) fish[k] = readLong(in);
        for (int k = 0; k < m; k++) baits[k] = readLong(in);
        Arrays.sort(fish);
        Arrays.sort(baits);
        int i = 0;
        long ans = 0;
        for (long b : baits) {
            // skip fish this bait (and every later, larger bait) cannot catch
            while (i < n && fish[i] <= b) i++;
            for (int used = 0; i < n && used < 3; used++, i++) ans++;
        }
        System.out.println(ans);
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	fish := make([]int, n)
	baits := make([]int, m)
	for k := range fish {
		fish[k] = next()
	}
	for k := range baits {
		baits[k] = next()
	}
	sort.Ints(fish)
	sort.Ints(baits)
	i, ans := 0, 0
	for _, b := range baits {
		// skip fish this bait (and every later, larger bait) cannot catch
		for i < n && fish[i] <= b {
			i++
		}
		for used := 0; i < n && used < 3; used++ {
			ans++
			i++
		}
	}
	fmt.Println(ans)
}
